const visual = {
  prepare: function (input) {
    return [
      { kind: 'text', payload: '支点' },
      { kind: 'text', payload: '动力臂' },
      { kind: 'text', payload: '阻力臂' },
      { kind: 'text', payload: '动力臂 : 阻力臂 = 3 : 2' }
    ];
  },
  render: function (input, metrics) {
    var S = (typeof visualSdk !== 'undefined') ? visualSdk : globalThis.visualSdk;
    var W = input.viewport.widthDu;
    var H = input.viewport.heightDu;
    var i;

    function pick(n) {
      var m = null;
      if (Array.isArray(metrics)) { m = metrics[n]; }
      else if (metrics && Array.isArray(metrics.items)) { m = metrics.items[n]; }
      else if (metrics && Array.isArray(metrics.texts)) { m = metrics.texts[n]; }
      var w = (m && typeof m.width === 'number') ? m.width : 0;
      var h = (m && typeof m.height === 'number') ? m.height : 0;
      return { w: w, h: h };
    }

    var fs = 16;
    var m0 = pick(0);
    if (m0.h > 6 && m0.h < 60) { fs = m0.h; }

    var groundY = H * 0.76;
    var barH = Math.max(8, Math.min(14, H * 0.026));
    var xA = W * 0.10;
    var L = W * 0.62;
    var xB = xA + L;
    var px = xA + L * 0.6;
    var barY = groundY - Math.max(50, H * 0.14);
    var barTop = barY - barH / 2;
    var barBot = barY + barH / 2;
    var xTip = xB + Math.min(18, W * 0.02);

    var rockW = Math.min(W * 0.15, W - xB - 26);
    if (!(rockW > 40)) { rockW = 40; }
    var rockH = Math.min(H * 0.23, 112);
    var rx = xB - 4;
    var rockPts = [
      [rx, groundY],
      [rx + rockW * 0.06, groundY - rockH * 0.60],
      [rx + rockW * 0.30, groundY - rockH * 0.99],
      [rx + rockW * 0.60, groundY - rockH * 0.86],
      [rx + rockW * 0.90, groundY - rockH * 0.40],
      [rx + rockW, groundY - rockH * 0.04],
      [rx + rockW, groundY]
    ];

    var fulHalf = Math.max(18, Math.min(34, W * 0.042));
    var dimY = barY - Math.max(56, H * 0.16);

    var rockCmds = ['M', rockPts[0][0], rockPts[0][1]];
    for (i = 1; i < rockPts.length; i++) {
      rockCmds.push('L', rockPts[i][0], rockPts[i][1]);
    }
    rockCmds.push('Z');

    var tickXs = [xA, px - 8, px + 8, xB];
    var tickCmds = [];
    for (i = 0; i < tickXs.length; i++) {
      tickCmds.push('M', tickXs[i], dimY - 7, 'L', tickXs[i], dimY + 7);
    }

    var paths = [
      { id: 'band', commands: ['M', 0, groundY, 'L', W, groundY, 'L', W, H, 'L', 0, H, 'Z'] },
      { id: 'ground', commands: ['M', 0, groundY, 'L', W, groundY] },
      { id: 'bar', commands: ['M', xA, barTop, 'L', xTip, barTop, 'L', xTip, barBot, 'L', xA, barBot, 'Z'] },
      { id: 'rock', commands: rockCmds },
      { id: 'fulcrum', commands: ['M', px - fulHalf, groundY, 'L', px, barBot + 2, 'L', px + fulHalf, groundY, 'Z'] },
      { id: 'force', commands: S.arrow(xA, barY - 54, xA, barTop - 8, {}) },
      { id: 'dimp', commands: S.polyline([[xA, dimY], [px - 8, dimY]]) },
      { id: 'dimr', commands: S.polyline([[px + 8, dimY], [xB, dimY]]) },
      { id: 'ticks', commands: tickCmds },
      { id: 'guide', commands: ['M', px, barTop - 4, 'L', px, dimY - 10] }
    ];

    var root = {
      type: 'group',
      children: [
        { type: 'path', pathId: 'band', fill: '#eef1f4', stroke: 'none' },
        { type: 'path', pathId: 'ground', stroke: '#6b7785', strokeWidth: Math.max(2, H * 0.006) },
        { type: 'path', pathId: 'bar', fill: '#c98a4b', stroke: '#8a5a28', strokeWidth: 2 },
        { type: 'path', pathId: 'rock', fill: '#a8b0b8', stroke: '#6d7783', strokeWidth: 2 },
        { type: 'path', pathId: 'fulcrum', fill: '#7f8ea0', stroke: '#4a5866', strokeWidth: 2 },
        { type: 'path', pathId: 'force', stroke: '#c0392b', strokeWidth: 3 },
        { type: 'path', pathId: 'guide', stroke: '#9fb0c2', strokeWidth: 1.2 },
        { type: 'path', pathId: 'dimp', stroke: '#1f6fb2', strokeWidth: 1.6 },
        { type: 'path', pathId: 'dimr', stroke: '#1f6fb2', strokeWidth: 1.6 },
        { type: 'path', pathId: 'ticks', stroke: '#1f6fb2', strokeWidth: 1.6 },
        { type: 'label', text: '动力臂', x: (xA + px) / 2, y: dimY - fs * 0.9, fontSize: fs, fill: '#1f6fb2', textAnchor: 'middle' },
        { type: 'label', text: '阻力臂', x: (px + xB) / 2, y: dimY - fs * 0.9, fontSize: fs, fill: '#1f6fb2', textAnchor: 'middle' },
        { type: 'label', text: '支点', x: px - fulHalf - 8, y: groundY - fs * 0.4, fontSize: fs, fill: '#3a4757', textAnchor: 'end' },
        { type: 'label', text: '动力臂 : 阻力臂 = 3 : 2', x: W / 2, y: fs * 1.8, fontSize: fs, fill: '#26354a', textAnchor: 'middle' }
      ]
    };

    return {
      schemaVersion: 1,
      sceneId: 'lever-rock',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: W, height: H },
      paths: paths,
      root: root
    };
  }
};
